def random_walk(grid, start, end):
    def is_valid_move(x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == 0

    def dfs(x, y, visited):
        if (x, y) == end:
            return True
        visited.add((x, y))
        moves = [(x+1, y), (x-1, y), (x, y+1), (x, y-1)]
        random.shuffle(moves)  # Randomize the order of moves
        for nx, ny in moves:
            if is_valid_move(nx, ny) and (nx, ny) not in visited:
                if dfs(nx, ny, visited):
                    return True
        return False

